SELECT u.*, ui."FILE_NO" AS "PROFILE_FILE_NO", ui."FILE_NAME" AS "PROFILE_FILE_NAME", ui."ORI_NAME" AS "PROFILE_ORI_NAME", r.*, EXISTS ( SELECT 1 FROM "FOLLOW" f WHERE f."USER_FOLLOWER" = u."USER_NO" AND f."USER_FOLLOWING" = #{userNo} ) AS "MUTUAL" FROM "FOLLOW" f INNER JOIN "USER" u ON u."USER_NO" = f."USER_FOLLOWING" LEFT JOIN "USER_IMG" ui USING ("USER_NO") LEFT JOIN "USER_ROLE" USING ("USER_NO") LEFT JOIN "ROLE" r USING ("ROLE_NO") WHERE f."USER_FOLLOWER" = #{userNo}
AND upper(u."USER_NICKNAME") LIKE '%' || upper(#{search}) || '%'
ORDER BY u."USER_NO" LIMIT #{perPage} OFFSET #{startNum}

SELECT u.*, ui."FILE_NO" AS "PROFILE_FILE_NO", ui."FILE_NAME" AS "PROFILE_FILE_NAME", ui."ORI_NAME" AS "PROFILE_ORI_NAME", r.*, EXISTS ( SELECT 1 FROM "FOLLOW" f WHERE f."USER_FOLLOWER" = #{userNo} AND f."USER_FOLLOWING" = u."USER_NO" ) AS "MUTUAL" FROM "FOLLOW" f INNER JOIN "USER" u ON u."USER_NO" = f."USER_FOLLOWER" LEFT JOIN "USER_IMG" ui USING ("USER_NO") LEFT JOIN "USER_ROLE" USING ("USER_NO") LEFT JOIN "ROLE" r USING ("ROLE_NO") WHERE f."USER_FOLLOWING" = #{userNo}
AND upper(u."USER_NICKNAME") LIKE '%' || upper(#{search}) || '%'
ORDER BY u."USER_NO" LIMIT #{perPage} OFFSET #{startNum}

SELECT EXISTS (
	SELECT 1
	FROM "FOLLOW"
	WHERE "USER_FOLLOWER" = #{userFollower}
	AND "USER_FOLLOWING" = #{userFollowing}
)
